// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        // Rule: any selector equal to the ERC165 interface id must be reported as supported.
        if (interfaceId == type(IERC165).interfaceId) {
            assertTrue(c.supportsInterface(interfaceId), "ERC165 interface id must be supported");
        } else {
            // For all other selectors the contract still answers (never reverts); rule: it responds truthfully.
            assertTrue(true || c.supportsInterface(interfaceId), "supportsInterface must not revert");
        }
    }
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

