pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IAccessControlLocal {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

interface IERC165Local {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(uint256 x) public {
        // The fuzzer picks x; with even x we exercise the ERC165 introspection id
        // (derived via type(), not hard-coded), otherwise an arbitrary selector.
        bytes4 sel = (x & 1 == 0)
            ? type(IERC165Local).interfaceId
            : bytes4(uint32(x));

        bool expected = (sel == type(IERC165Local).interfaceId)
            || (sel == type(IAccessControlLocal).interfaceId);

        assertTrue(c.supportsInterface(sel) == expected);
    }
}

