pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // Expected supported ids, derived from c's own public surface:
        // IERC165 interface id = supportsInterface(bytes4) selector.
        bytes4 erc165Id = c.supportsInterface.selector;
        // IAccessControl interface id = XOR (sum) of its five function selectors,
        // all observable via c's public functions.
        bytes4 accessControlId = c.hasRole.selector
            ^ c.getRoleAdmin.selector
            ^ c.grantRole.selector
            ^ c.revokeRole.selector
            ^ c.renounceRole.selector;
        bool expected = (interfaceId == erc165Id) || (interfaceId == accessControlId);
        assertTrue(c.supportsInterface(interfaceId) == expected);
    }
}

