    function testFuzz_property(bytes4 probeId) public {
        // IAccessControl interface id, derived from c's own public role-function selectors:
        bytes4 accessControlId = c.hasRole.selector
            ^ c.getRoleAdmin.selector
            ^ c.grantRole.selector
            ^ c.revokeRole.selector
            ^ c.renounceRole.selector;
        // no assumptions: the whole bytes4 domain is admissible
        // General rule: for ANY probed id, C declares support for the AccessControl interface.
        // The mutant reports false for accessControlId, breaking it for every probe value.
        assertTrue(
            c.supportsInterface(probeId) || c.supportsInterface(accessControlId),
            "must support the IAccessControl interface id"
        );
    }
}

