pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address actor) public {
        // The only members ever granted are this test contract (deployer) and c itself
        // for TIMELOCK_ADMIN_ROLE; PROPOSER_ROLE and EXECUTOR_ROLE were granted to nobody.
        // Restrict to the wide admissible domain: actor not a member, role any bytes32.
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        // General rule: an account that was never granted a role does not have it.
        assertTrue(!c.hasRole(role, actor));
    }
}

