pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        vm.prank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), actor);

        // A granted account must report holding the role; a non-granted
        // role must report not holding it. The mutant always returns false.
        assertTrue(c.hasRole(c.PROPOSER_ROLE(), actor));
    }
}

