pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(uint256 selector) public {
        selector = bound(selector, 0, 2);
        bytes32 role;
        if (selector == 0) {
            role = c.TIMELOCK_ADMIN_ROLE();
        } else if (selector == 1) {
            role = c.PROPOSER_ROLE();
        } else {
            role = c.EXECUTOR_ROLE();
        }
        // General rule: each configured role's admin is TIMELOCK_ADMIN_ROLE.
        assertTrue(c.getRoleAdmin(role) == c.TIMELOCK_ADMIN_ROLE());
    }
}

